from pathlib import Path
import base64,json,html
import pandas as pd
import numpy as np
ROOT=Path(__file__).resolve().parent;R=ROOT/'results'
labels={'ols':'OLS reference','ridge':'Ridge','lasso':'Lasso','en':'Elastic Net','gbm_missing':'LightGBM: missing preserved','gbm_median':'LightGBM: median filled','gbm_median_matched':'LightGBM: median, matched settings','annual_blend':'Annually selected blend'}

def table(df):return df.to_markdown(index=False)

def main():
    pm=pd.read_csv(R/'portfolio_metrics.csv');pred=pd.read_csv(R/'prediction_metrics.csv');yr=pd.read_csv(R/'yearly_returns.csv');unc=pd.read_csv(R/'paired_uncertainty.csv');folds=json.loads((R/'annual_choices.json').read_text());audit=json.loads((R/'verification.json').read_text())
    net=pm[pm.cost_bps==20].set_index('model');gross=pm[pm.cost_bps==0].set_index('model');pr=pred[pred.universe=='eligible'].set_index('model')
    tab=pd.DataFrame({'Model':[labels[n] for n in net.index],'Net CAGR':[f'{v:.2%}' for v in net.cagr],'IR, gross':[f'{gross.loc[n,"ir"]:.2f}' for n in net.index],'IR, net':[f'{v:.2f}' for v in net.ir],'Beta':[f'{v:+.3f}' for v in net.beta],'Max drawdown':[f'{v:.2%}' for v in net.max_drawdown],'Mean rank IC':[f'{pr.loc[n,"mean_monthly_ic"]:.4f}' for n in net.index]})
    pt=pd.DataFrame({'Model':[labels[n] for n in pr.index],'OOS R², eligible':[('not applicable' if pd.isna(v) else f'{v:.3%}') for v in pr.oos_r2],'Rank IC months':pr.months_with_defined_ic.astype(int).values,'Constant-forecast months':pr.constant_forecast_months.astype(int).values})
    by=yr.pivot(index='model',columns='year',values='net_return_20bps').reindex(net.index);by.index=[labels[x] for x in by.index];by=by.map(lambda x:f'{x:.2%}').reset_index(names='Model')
    ft=pd.DataFrame([{'Test year':f['year'],'Training through':f['train_end'],'Validation':f['validation_start']+' to '+f['validation_end'],'Selected blend':f['annual_blend'],'Trees, missing':f['hyperparameters']['gbm_missing']['rounds'],'Trees, filled':f['hyperparameters']['gbm_median']['rounds']} for f in folds])
    ut=pd.DataFrame([{'Paired comparison':labels[r.model_a]+' minus '+labels[r.model_b],'Annual mean difference':f'{100*r.annualized_arithmetic_mean_difference:+.2f} pp','95% interval':f'[{100*r.ci_low:+.2f}, {100*r.ci_high:+.2f}] pp'} for r in unc.itertuples()])
    mt=pd.DataFrame([{'Model':labels[v['model']],'Missing-return positions':v['missing_return_positions'],'Mean unobserved gross exposure':f'{net.loc[v["model"],"mean_missing_gross"]:.3%}','Net CAGR, adverse marking':f'{v["adverse_missing_cagr"]:.2%}'} for v in audit['portfolio_checks']])
    best=net.ir.idxmax();missing=net.loc['gbm_missing'];filled=net.loc['gbm_median'];matched=net.loc['gbm_median_matched'];ridge=net.loc['ridge']
    sections=[]
    def add(title,text):sections.append((title,text))
    add('What was completed', 'Seven fixed model variants and an annually selected blend were evaluated over all 68 holding months from January 2021 through August 2026. Every model used the same 147 characteristics, original next-month excess-return target, annual time splits, investable-stock screen, portfolio rules and cost accounting. The two uploaded raw datasets remain unchanged; only the numerical dataset was needed.\n\nThe annual selection bug is repaired in the experiment: each year’s blend is selected using only that year’s preceding two-year validation window. Later validation outcomes are never pooled to choose earlier forecasts.')
    add('Main findings',f'The highest observed information ratio after the assumed 20-basis-point trading cost was **{labels[best]}: {net.loc[best,"ir"]:.2f}**, with a net CAGR of **{net.loc[best,"cagr"]:.2%}**. This is a descriptive historical result, not proof that it is the best future model.\n\nLightGBM with missing values preserved had a net IR of **{missing.ir:.2f}**, versus **{filled.ir:.2f}** for separately tuned median-filled LightGBM and **{matched.ir:.2f}** for median-filled LightGBM with the missing-preserved variant’s settings. Ridge had a net IR of **{ridge.ir:.2f}**. Read the paired uncertainty intervals before attributing these differences to a reliable advantage. The Ridge-minus-LightGBM-missing gap is supported by the descriptive paired interval in this setup, but the missing-versus-median intervals include zero.\n\nThese headline returns are **provisional**: Ridge holds 54 stock-month positions without observed outcomes. The base case marks those stock returns at zero; under the stated adverse marking scenario, Ridge CAGR becomes approximately **−1.10%**. The unresolved positions are listed in missing_return_positions.csv. This sensitivity is material and should be addressed before presenting returns as submission-ready.\n\nThis experiment deliberately gives all algorithms the same unmodified return target. The existing team code gave LightGBM a month-demeaned, clipped target while the linear models used original returns. Consequently, this is a fair comparison under a common objective; it does not reproduce the team’s earlier saved performance or rule out better results from a separately specified ranking-oriented experiment.')
    add('Portfolio comparison', 'Net means 20 bps charged per dollar traded, including opening trades. CAGR is compounded annual growth; IR measures excess over the cash-plus-4% hurdle. Beta is measured against the supplied S&P 500 price series.\n\n'+table(tab)+'\n\nAll portfolios held 100 longs and 100 shorts in each of 68 months, stayed within 200% gross and the competition’s ±50% net band, and had both legs present with no duplicated stock-month positions. Satisfying those limits does not certify market neutrality: read beta and its standard error in portfolio_metrics.csv. The inherited nominal 2% position cap applies before scaling the legs and is not an enforced final cap.')
    add('Prediction quality and tied forecasts',table(pt)+'\n\nR² compares squared forecast error with predicting zero; it is reported on the common eligible universe here. The full-universe version is also supplied. Rank IC is monthly Spearman correlation, averaged only over months where it is defined. The blend is a ranking score, so return-unit R² is inappropriate.\n\nIf regularization collapses a model to a constant, it has no within-month stock-selection signal. To keep the same portfolio construction for every model, tied scores follow deterministic input/PERMNO ordering, with the short selection traversing the reverse order. Portfolio returns in those months are mechanical fallback results, not evidence of prediction skill. The constant-month counts above make this limitation visible.')
    add('Performance by year',table(by)+'\n\n2026 covers January–August only; its number is an eight-month compounded return, not a full-year return. All entries use 20 bps per dollar traded. Benchmark and market yearly returns are in yearly_returns.csv.')
    add('Annual choices',table(ft)+'\n\nModel hyperparameters minimize validation MSE. The annual blend maximizes mean validation-month rank IC across the five predeclared candidates. Hyperparameters, candidate scores, split dates and row counts are recorded in annual_choices.json. Some boosting fits stop after very few trees; this is the validation choice under the shared raw-return objective, not a failed training run. Ridge occasionally selects a grid boundary, so this finite grid does not establish an optimal Ridge setting.')
    add('Uncertainty in model differences',table(ut)+'\n\nThese are paired circular six-month block-bootstrap intervals based on 2,000 draws of the same 68 months, using identical sampled months for both models. The statistic is an annualized arithmetic mean return difference, not a CAGR or IR difference. Intervals containing zero do not support a clear directional conclusion at this descriptive confidence level. The exercise has no untouched new holdout, and these intervals are not adjusted for multiple comparisons or historical strategy development.')
    add('Missing outcomes and implementation limits',table(mt)+'\n\nBase returns explicitly mark positions with unavailable forward outcomes at zero raw stock return; such stocks are never removed using their future outcome. The adverse marking scenario assigns −100% to missing long-stock returns and +100% to missing short-stock returns, keeping the base holdings and 20-bps trading charge fixed. It is a sensitivity illustration, not a worst-case bound, and does not rerun historical beta feedback under the alternate marks. Missing delisting or other terminal outcomes still need resolution before a submission-quality performance claim.\n\nAccounting reconstructs raw forward returns using the source risk-free rate, verified from ret minus ret_exc. Total portfolio return is cash + Σ w × (raw stock return − cash); financing at the same cash rate is assumed. This handles nonzero net exposure without pretending the panel RF and TB3MS cancel. Trade sizes compare target weights against drifted prior positions, including prior costs in NAV. Initial entry is charged; final liquidation is not. Stock-borrow fees, recalls, asymmetric financing and nonlinear liquidity costs are not modeled.\n\nThe model-selection repair removes a specific forward-looking choice, but cannot erase prior human inspection of 2021–2026 results. The inherited portfolio policy was developed using those historical results. Treat this as a controlled historical comparison. All labels remain original: some missing ticker/company labels require verification before competition submission.')
    add('Verification and next action',f'The numerical file’s SHA-256 matches the distributed dataset documentation. The panel has 529,082 rows, 147 selected predictors, and no duplicate security-month keys. {audit["forward_pairs_checked"]:,} available forward/current return pairs matched to within numerical precision. Observed feature values are identical across missingness variants. All annual split boundaries and every model’s 68 portfolios were checked. Five focused tests cover annual-selection independence from test outcomes, calendar smoothing, initial-loss drawdown, financing arithmetic and saved split dates.\n\nUse these results to explain what changed and why, rather than announcing a winner from the historical test table. A useful next experiment would predeclare a common ranking-oriented or robust target for all models and rerun the same comparison, with no portfolio retuning. It is outside the present experiment and has not been run.\n\nTo rerun or integrate the work, follow README.md. The complete deliverable includes scripts, pinned dependencies, the frozen protocol, annual choices, predictions, holdings, metrics, plots and verification outputs. Raw datasets and regenerable caches are excluded.')
    md='# Fair model-comparison experiment\n\n'
    for title,body in sections:md+='## '+title+'\n\n'+body+'\n\n'
    (ROOT/'REPORT.md').write_text(md)
    # HTML is a self-contained reading copy; charts are embedded.
    try:
        import markdown
        rendered=markdown.markdown(md,extensions=['tables'])
    except ImportError:
        rendered='<pre style="white-space:pre-wrap">'+html.escape(md)+'</pre>'
    images=''
    for fn in ['comparison.png','cost_sensitivity.png']:
        images+='<img alt="'+fn+'" src="data:image/png;base64,'+base64.b64encode((R/fn).read_bytes()).decode()+'">'
    page='<!doctype html><html lang="en"><meta charset="utf-8"><title>FIAM model comparison</title><style>body{font:16px/1.6 system-ui,sans-serif;max-width:1150px;margin:40px auto;padding:0 24px;color:#172433}h1{font-size:32px}h2{font-size:23px;margin-top:36px;color:#173f5f}table{border-collapse:collapse;width:100%;font-size:13px;margin:20px 0}th,td{padding:9px;border-bottom:1px solid #dbe3e9;text-align:left}th{background:#eaf1f7}img{max-width:100%;margin:20px 0}code{background:#eef2f6;padding:2px 4px}p{max-width:1050px}@media print{body{margin:0}h2{break-after:avoid}tr,img{break-inside:avoid}}</style><body>'+rendered+images+'</body></html>'
    (ROOT.parent/'FIAM_Model_Comparison_Report.html').write_text(page)
    print(tab.to_string(index=False))

if __name__=='__main__':main()
